args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-30-pending-barley-module-similarity');w<-file.path(W,'matrix');D<-file.path(P,'results/plot_data');library(ggplot2);library(jsonlite);source(file.path(P,'biofigure/scripts/figure_style.R'));bf_complexheatmap_font(bf_font('Arial'))
