qc<-list(stem=stem,width_mm=183,height_mm=165,plot_data_files=c(matrixfile,orderfile,memberfile),transform='Author Data9 unique PanBaRT20 gene-module memberships; cosine=intersection/sqrt(sizeA*sizeB), rounded4decimals as author05. Original C1-C6 source labels retained; source group orderC6,C2,C4,C3,C1,C5. Within-group deterministic average-Euclidean clustering on full cosine profiles computed once and shared by rows/columns. Not original WGCNA rerun or final publication leaf-order identity. Old archived simulation Fig3a+ED5b is retained only as history; this is first bound real-Data9 numeric completion for this selected heatmap scope.',counts=list(annotation_rows=nrow(z),unique_memberships=nrow(mem),genes=length(genes),modules=length(modules),cells=length(cosine)),palette=as.list(cc));write_json(qc,file.path(w,'input-qc.json'),auto_unbox=TRUE,pretty=TRUE,digits=NA);capture.output(sessionInfo(),file=file.path(w,'prepare-sessionInfo.txt'));cat('738 modules and544644 true cosine cells prepared\n')
